scaffold_css:
/* SCAFFOLD CSS — optional reference patterns. These classes are not required.
   Use what fits your structure. Ignore the rest. */

/* Navigation */

.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-primary-100);
  padding: var(--spacing-md) 0;
}

.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--spacing-lg);
}

.logo {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: var(--text-h3);
  color: var(--color-primary);
  text-decoration: none;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--spacing-lg);
  list-style: none;
}
.nav-links a {
  color: var(--color-text-secondary);
  text-decoration: none;
  font-size: var(--text-body);
  transition: color var(--duration-fast) var(--ease-smooth);
}
.nav-links a:hover {
  color: var(--color-primary);
}

/* Buttons */

.btn-secondary {
  background: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
  border-radius: var(--radius-md);
}
.btn-secondary:hover {
  background: var(--color-primary);
  color: white;
}
.btn-large {
  padding: var(--spacing-lg) var(--spacing-2xl);
  font-size: var(--text-h3);
}

/* Hero shared */

.hero-ctas {
  display: flex;
  gap: var(--spacing-md);
  flex-wrap: wrap;
  margin-top: var(--spacing-lg);
}

.hero-subtitle,
.hero-tagline,
.hero-excerpt {
  font-size: var(--text-h3);
  color: var(--color-text-secondary);
  line-height: var(--leading-h3);
  margin-top: var(--spacing-md);
}

.hero-meta {
  display: flex;
  gap: var(--spacing-md);
  color: var(--color-text-tertiary);
  font-size: var(--text-small);
  margin-top: var(--spacing-sm);
}

.hero-services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--spacing-lg);
  margin-top: var(--spacing-xl);
}
.service-card {
  background: var(--color-surface-elevated);
  padding: var(--spacing-lg);
  border-radius: var(--radius-md);
}

.hero-carousel {
  display: flex;
  gap: var(--spacing-lg);
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  margin-top: var(--spacing-lg);
}
.carousel-item {
  flex: 0 0 280px;
  scroll-snap-align: start;
}

.hero-filters {
  display: flex;
  gap: var(--spacing-sm);
  flex-wrap: wrap;
  margin-top: var(--spacing-md);
}
.filter-link {
  padding: var(--spacing-xs) var(--spacing-md);
  background: var(--color-surface-elevated);
  border-radius: var(--radius-full);
  font-size: var(--text-small);
  text-decoration: none;
  color: var(--color-text-secondary);
}

.play-button {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  background: transparent;
  border: 2px solid var(--color-primary);
  border-radius: var(--radius-full);
  padding: var(--spacing-md) var(--spacing-lg);
  cursor: pointer;
  color: var(--color-primary);
  font-size: var(--text-body);
}

.hero-testimonial-featured {
  max-width: 700px;
  margin: var(--spacing-xl) auto;
}
.hero-testimonial-featured blockquote {
  font-family: var(--font-display);
  font-size: var(--text-h3);
  font-style: italic;
  color: var(--color-text);
  margin-bottom: var(--spacing-lg);
}

.configurator-preview {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xl);
  margin-top: var(--spacing-xl);
}
.config-3d-viewer {
  background: var(--color-surface-elevated);
  border-radius: var(--radius-lg);
  aspect-ratio: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}
.config-placeholder {
  color: var(--color-text-secondary);
  font-size: var(--text-small);
}
.config-options {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-lg);
}
.config-price {
  display: flex;
  align-items: baseline;
  gap: var(--spacing-sm);
}
.price-label {
  font-size: var(--text-small);
  color: var(--color-text-secondary);
}
.price-value {
  font-family: var(--font-display);
  font-size: var(--text-h2);
  font-weight: 700;
  color: var(--color-primary);
}
.color-options {
  display: flex;
  gap: var(--spacing-sm);
}
.color-swatch {
  width: 32px;
  height: 32px;
  border-radius: var(--radius-full);
  border: 2px solid transparent;
  cursor: pointer;
}
.color-swatch.active {
  border-color: var(--color-text);
}

/* Sections */

.section-title {
  font-family: var(--font-display);
  font-size: var(--text-h2);
  line-height: var(--leading-h2);
  font-weight: 700;
  margin-bottom: var(--spacing-lg);
}
.section-intro {
  font-size: var(--text-body);
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-xl);
  max-width: 640px;
}

/* Trust grid */

.trust-section {
  padding: var(--spacing-2xl) 0;
}
.trust-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: var(--spacing-xl);
  text-align: center;
}
.trust-number {
  font-family: var(--font-display);
  font-size: var(--text-h1);
  font-weight: 700;
  color: var(--color-primary);
}
.trust-label {
  font-size: var(--text-small);
  color: var(--color-text-secondary);
  margin-top: var(--spacing-xs);
}

/* Social proof */

.social-proof {
  padding: var(--spacing-2xl) 0;
  background: var(--color-surface-elevated);
}
.testimonial-author {
  display: flex;
  align-items: center;
  gap: var(--spacing-md);
  margin-top: var(--spacing-md);
}
.author-avatar {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-full);
  object-fit: cover;
}

/* Features */

.features {
  padding: var(--spacing-2xl) 0;
}
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--spacing-lg);
}
.feature-card {
  background: var(--color-surface-elevated);
  padding: var(--spacing-lg);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-primary-100);
}
.feature-card h3 {
  font-family: var(--font-display);
  font-size: var(--text-h3);
  font-weight: 600;
  margin-bottom: var(--spacing-sm);
  color: var(--color-text);
}
.feature-card p {
  color: var(--color-text-secondary);
  font-size: var(--text-body);
}

/* FAQ */

.faq {
  padding: var(--spacing-2xl) 0;
}
.faq-list {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}
.faq-item {
  border: 1px solid var(--color-primary-100);
  border-radius: var(--radius-md);
  overflow: hidden;
}
.faq-item summary {
  cursor: pointer;
  padding: var(--spacing-lg);
  font-weight: 600;
  list-style: none;
  color: var(--color-text);
}
.faq-item summary::-webkit-details-marker { display: none; }
.faq-item p {
  padding: 0 var(--spacing-lg) var(--spacing-lg);
  color: var(--color-text-secondary);
}

/* CTA */

.cta {
  padding: var(--spacing-2xl) 0;
  background: var(--color-primary);
  text-align: center;
}
.cta-title {
  font-family: var(--font-display);
  font-size: var(--text-h2);
  font-weight: 700;
  color: white;
  margin-bottom: var(--spacing-md);
}
.cta-subtitle {
  color: rgba(255,255,255,0.8);
  font-size: var(--text-body);
  margin-bottom: var(--spacing-xl);
}

/* Footer */

.footer {
  padding: var(--spacing-2xl) 0;
  background: var(--color-surface-elevated);
  border-top: 1px solid var(--color-primary-100);
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: var(--spacing-2xl);
  margin-bottom: var(--spacing-xl);
}
.footer-brand p {
  color: var(--color-text-secondary);
  margin-top: var(--spacing-sm);
  font-size: var(--text-small);
}
.footer-links h4 {
  font-weight: 600;
  margin-bottom: var(--spacing-md);
  color: var(--color-text);
}
.footer-links ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}
.footer-links a {
  color: var(--color-text-secondary);
  text-decoration: none;
  font-size: var(--text-small);
  transition: color var(--duration-fast) var(--ease-smooth);
}
.footer-links a:hover {
  color: var(--color-primary);
}
.footer-bottom {
  padding-top: var(--spacing-lg);
  border-top: 1px solid var(--color-primary-100);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: var(--text-small);
  color: var(--color-text-tertiary);
}

.logo-wordmark {
  font-family: var(--font-display);
  font-size: var(--text-h3);
  font-weight: 700;
  color: var(--color-text-secondary);
}

/* Hero Section */

.hero {
  position: relative;
  min-height: 80vh;
  display: flex;
  align-items: center;
  overflow: hidden;
}

.hero-content {
  width: 100%;
  max-width: 731px;
  margin-inline: auto;
  text-align: center;
  padding: var(--spacing-xl);
}

.hero-screenshot {
  border-radius: var(--radius-lg);
  box-shadow: 0 34px 41px -12px rgba(0, 0, 0, 0.29);
  overflow: hidden;
}

/* Trust Signals */

.trust-section {
  padding: var(--spacing-2xl) var(--spacing-xl);
  background: var(--color-surface-elevated);
}

.logos-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-2xl);
  flex-wrap: wrap;
}  .logo-item {
  opacity: 0.6;
  filter: grayscale(100%);
  transition: all var(--duration-fast) var(--ease-smooth);
}  .logo-item:hover {
  opacity: 1;
  filter: grayscale(0%);
}

.credentials-list {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-md);
}  .credential-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-xs);
  padding: var(--spacing-xs) var(--spacing-sm);
  background: var(--color-primary-100);
  border-radius: var(--radius-sm);
  font-size: var(--text-small);
}

